/**
 * @summary List send records for a user
 */
export const getListSendRecordsUrl = (params: ListSendRecordsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/send-records?${stringifiedParams}`
    : `/api/send-records`;
};

export const listSendRecords = async (
  params: ListSendRecordsParams,
  options?: RequestInit,
): Promise<SendRecordWithDetails[]> => {
  return customFetch<SendRecordWithDetails[]>(getListSendRecordsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListSendRecordsQueryKey = (params?: ListSendRecordsParams) => {
  return [`/api/send-records`, ...(params ? [params] : [])] as const;
};

export const getListSendRecordsQueryOptions = <
  TData = Awaited<ReturnType<typeof listSendRecords>>,
  TError = ErrorType<unknown>,
>(
  params: ListSendRecordsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listSendRecords>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListSendRecordsQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listSendRecords>>> = ({
    signal,
  }) => listSendRecords(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listSendRecords>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListSendRecordsQueryResult = NonNullable<
  Awaited<ReturnType<typeof listSendRecords>>
>;
export type ListSendRecordsQueryError = ErrorType<unknown>;

/**
 * @summary List send records for a user
 */

export function useListSendRecords<
  TData = Awaited<ReturnType<typeof listSendRecords>>,
  TError = ErrorType<unknown>,
>(
  params: ListSendRecordsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listSendRecords>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getListSendRecordsQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

